import fs from "node:fs";
import path from "node:path";
import yaml from "js-yaml";
import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";

/**
 * The notebook holds living articles — pieces that get revised rather than
 * dated. One category per project under ~/code/open-concept-lab/ai/.
 *
 * Written by hand rather than autogenerated. Autogeneration derives the tree
 * from the files, and the files do not know that a project with one page and a
 * project with three are the same kind of thing: one rendered as a bare
 * directory name, the other as a tree. Here every project has the same shape —
 * a name, its stage, a few words saying what it is, and its own pages, the
 * overview included.
 *
 * The stage comes from data/projects.yml, so it is set in one place and the
 * home page and the sidebar cannot disagree.
 */

type ProjectRow = { name: string; tone?: string };

const projects = (
  yaml.load(
    fs.readFileSync(path.join(__dirname, "data/projects.yml"), "utf8"),
  ) as { projects: ProjectRow[] }
).projects;

const toneOf = (name: string): string =>
  projects.find((p) => p.name === name)?.tone ?? "draft";

const project = (
  id: string,
  blurb: string,
  items: { label: string; doc: string }[],
) => ({
  type: "category" as const,
  label: id,
  collapsed: false,
  customProps: { blurb, status: toneOf(id) },
  items: [
    { type: "doc" as const, id: `${id}/index`, label: "Overview" },
    ...items.map((i) => ({
      type: "doc" as const,
      id: `${id}/${i.doc}`,
      label: i.label,
    })),
  ],
});

const sidebars: SidebarsConfig = {
  notebookSidebar: [
    { type: "doc", id: "index", label: "Notebook" },
    project("edit-slice", "what edits disturb", [
      { label: "Paper", doc: "review" },
      { label: "Evidence", doc: "ledger" },
    ]),
    project("edit-reach", "predicting reach", [
      { label: "Paper", doc: "paper" },
      { label: "Lab log", doc: "lab-log" },
    ]),
    project("rome-neighbors", "geometry", []),
    project("claim-graph", "claims as nodes", []),
    project("opz", "deployment labs", []),
    { type: "doc", id: "writing-here", label: "Writing here" },
  ],
};

export default sidebars;
